// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type ScatterPlotProps = Record<string, any>;

const ScatterPlot: React.FC<ScatterPlotProps> = ({
  backgroundColor = "#0E0E0F",
  transparentBackground = false,
  durationInSeconds = 5,
  axisColor = "#6B6B6B",
  pointColor = "#FFFFFF",
  xAxisLabel = "People carrying umbrellas.",
  yAxisLabel = "Wet streets.",
  pointCount = 24,
  textSize = 22,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const axisDrawFrames = 0.8 * fps;
  const labelFadeFrames = 0.3 * fps;
  const pointStaggerFrames = 0.06 * fps;
  const pointAnimFrames = 0.3 * fps;
  const exitDurationFrames = 0.4 * fps;
  const totalFrames = durationInSeconds * fps;

  // Data point generation (deterministic random, diagonal correlation, sorted for L->R entry)
  const points = useMemo(() => {
    const pts: { x: number; y: number }[] = [];
    const xStart = 280;
    const xEnd = 1640;
    const yBottom = 750;
    const yTop = 230;

    for (let i = 0; i < pointCount; i++) {
      const t = i / Math.max(1, pointCount - 1);
      
      const baseX = xStart + t * (xEnd - xStart);
      const baseY = yBottom + t * (yTop - yBottom); 

      // Apply some noise for scatter effect
      const xNoise = (random(`x-${i}`) - 0.5) * 120;
      const yNoise = (random(`y-${i}`) - 0.5) * 180;

      const x = Math.max(220, Math.min(1700, baseX + xNoise));
      const y = Math.max(180, Math.min(800, baseY + yNoise));

      pts.push({ x, y });
    }

    // Sort by X coordinate for left-to-right staggered animation
    return pts.sort((a, b) => a.x - b.x);
  }, [pointCount]);

  // Global exit animation
  const globalOpacity = interpolate(
    frame,
    [totalFrames - exitDurationFrames, totalFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Axis drawing progress
  const axisProgress = interpolate(frame, [0, axisDrawFrames], [0, 1], {
    easing: Easing.inOut(Easing.ease),
    extrapolateRight: "clamp",
  });

  // Label fade-in progress
  const labelOpacity = interpolate(
    frame,
    [axisDrawFrames, axisDrawFrames + labelFadeFrames],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, opacity: globalOpacity, transition: "none" }}>
      <svg width={width} height={height} style={{ overflow: "visible" }}>
        {/* X-Axis */}
        <line
          x1={200}
          y1={820}
          x2={200 + 1520 * axisProgress}
          y2={820}
          stroke={axisColor}
          strokeWidth={1}
          style={{ transition: "none" }}
        />

        {/* Y-Axis */}
        <line
          x1={200}
          y1={820}
          x2={200}
          y2={820 - 660 * axisProgress}
          stroke={axisColor}
          strokeWidth={1}
          style={{ transition: "none" }}
        />

        {/* Scatter Points */}
        {points.map((p, i) => {
          const startFrame = axisDrawFrames + i * pointStaggerFrames;
          const pointProgress = interpolate(
            frame,
            [startFrame, startFrame + pointAnimFrames],
            [0, 1],
            {
              easing: Easing.out(Easing.exp),
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          return (
            <circle
              key={i}
              cx={p.x}
              cy={p.y}
              r={5 * pointProgress}
              fill={pointColor}
              opacity={pointProgress}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>

      {/* X-Axis Label */}
      <div
        style={{
          position: "absolute",
          top: 870,
          left: 960,
          transform: "translateX(-50%)",
          fontFamily: interFamily,
          fontSize: textSize,
          fontWeight: 400,
          color: axisColor,
          opacity: labelOpacity,
          whiteSpace: "nowrap",
          transition: "none",
        }}
      >
        {xAxisLabel}
      </div>

      {/* Y-Axis Label */}
      <div
        style={{
          position: "absolute",
          top: 490, // Middle of the Y-axis (160 + 820) / 2
          left: 120,
          transform: "translate(-50%, -50%) rotate(-90deg)",
          fontFamily: interFamily,
          fontSize: textSize,
          fontWeight: 400,
          color: axisColor,
          opacity: labelOpacity,
          whiteSpace: "nowrap",
          transition: "none",
        }}
      >
        {yAxisLabel}
      </div>
    </AbsoluteFill>
  );
};

export default ScatterPlot;